function renderStats(){const e=document.getElementById("stats-grid");e&&"undefined"!=typeof BHOJA_INFO&&(e.innerHTML=BHOJA_INFO.quickStats.map(e=>`\n        <div class="stat-card">\n            <span class="stat-icon">${e.icon}</span>\n            <div class="stat-val">${e.value}</div>\n            <div class="stat-lbl">${e.label}</div>\n        </div>\n    `).join(""))}function renderTreatises(){const e=document.getElementById("treatises-grid");e&&"undefined"!=typeof SCHOLARLY_TREATISES&&(e.innerHTML=SCHOLARLY_TREATISES.map(e=>`\n        <div class="treatise-card">\n            <span class="status-tag">${e.attributionStatus}</span>\n            <h3>📖 ${e.title}</h3>\n            <p><strong>Discipline:</strong> ${e.discipline}</p>\n            <p>${e.summary}</p>\n        </div>\n    `).join(""))}function renderBhojpurCard(){const e=document.getElementById("bhojpur-card");e&&"undefined"!=typeof BHOJPUR_ARCHITECTURE&&(e.innerHTML=`\n        <div class="bhojpur-inner">\n            <h3>🛕 ${BHOJPUR_ARCHITECTURE.templeName}</h3>\n            <p><strong>Monolithic Lingam Dimensions:</strong> ${BHOJPUR_ARCHITECTURE.lingamDimensions}</p>\n            <ul class="notes-list">\n                ${BHOJPUR_ARCHITECTURE.architectureNotes.map(e=>`<li>✨ ${e}</li>`).join("")}\n            </ul>\n        </div>\n    `)}function renderTimeline(){const e=document.getElementById("timeline-container");e&&"undefined"!=typeof TIMELINE_EVENTS&&(e.innerHTML=TIMELINE_EVENTS.map(e=>`\n        <div class="timeline-card">\n            <div class="timeline-year">${e.year}</div>\n            <div class="timeline-content">\n                <h3>${e.title}</h3>\n                <p>${e.description}</p>\n            </div>\n        </div>\n    `).join(""))}function renderReferences(){const e=document.getElementById("references-list");e&&"undefined"!=typeof REFERENCES&&(e.innerHTML=REFERENCES.map(e=>`\n        <li>\n            <a href="${e.link}" target="_blank" rel="noopener noreferrer">📚 ${e.text}</a>\n        </li>\n    `).join(""))}function initThemeToggle(){const e=document.getElementById("theme-toggle");e&&e.addEventListener("click",()=>{const n=document.body.classList.toggle("light-theme");localStorage.setItem("theme",n?"light":"dark"),e.textContent=n?"🌙":"☀️"})}document.addEventListener("DOMContentLoaded",()=>{renderStats(),renderTreatises(),renderBhojpurCard(),renderTimeline(),renderReferences(),initThemeToggle()});